function localize(text: string): string {
  const direct = RU_TEXT[text];
  if (direct) return direct;
  const folded = text.toLocaleLowerCase();
  for (const [source, translated] of Object.entries(RU_TEXT)) {
    if (source.toLocaleLowerCase() === folded) {
      return text === text.toLocaleUpperCase() ? translated.toLocaleUpperCase() : translated;
    }
  }
  return text;
}
